// Enregistre l'inscription dans la mémoire du workflow (pas de Google Sheet).
// La liste se consulte dans l'Espace liste du site (onglet Jeu concours).
const store = $getWorkflowStaticData('global');
store.inscrits = store.inscrits || [];

const b = $input.first().json.body || {};
const clean = (v, max = 160) => String(v ?? '').replace(/\s+/g, ' ').trim().slice(0, max);
const reply = (extra) => [{ json: { ok: true, count: store.inscrits.length, isNew: false, ...extra } }];
if (b.website) return reply({}); // robot : on ignore sans rien enregistrer

const row = {
  id: 'C-' + Date.now().toString(36).toUpperCase() + Math.random().toString(36).slice(2, 5).toUpperCase(),
  date: new Date().toLocaleString('fr-FR', { timeZone: 'Europe/Paris', day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' }),
  name: clean(b.name, 120),
  email: clean(b.email).toLowerCase(),
  phone: clean(b.phone, 40),
  winner: false,
};
if (!row.name || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(row.email)) return reply({ ok: false, error: 'incomplet' });

// Une même adresse e-mail ne compte qu'une fois
if (store.inscrits.some((r) => r.email === row.email)) return reply({ already: true });
if (store.inscrits.length >= 5000) return reply({ ok: false, error: 'plein' });

store.inscrits.push(row);
return reply({
  isNew: true,
  name: row.name,
  email: row.email,
  list: clean(b.list, 60) || 'Leclercq des étoiles',
  contest: clean(b.contest, 120) || 'Jeu concours',
});

