// Nombre d'inscrits, affiché sur le site
const store = $getWorkflowStaticData('global');
return [{ json: { ok: true, count: (store.inscrits || []).length } }];

// Espace liste : lire la liste des inscrits, marquer un gagnant, supprimer une ligne.
// ⚠️ Remplacez CHANGEZ-MOI par la MÊME clé secrète que dans le workflow « Cotisations et soutien actif » :
// le site utilise une seule clé (Espace liste → Cotisations → Connexion n8n) pour les deux listes.
const CLE_SECRETE = 'CHANGEZ-MOI';

const b = $input.first().json.body || {};
const okKey = CLE_SECRETE !== 'CHANGEZ-MOI' && CLE_SECRETE.length >= 16 && String(b.key || '') === CLE_SECRETE;
if (!okKey) return [{ json: { ok: false, error: 'cle' } }];

const store = $getWorkflowStaticData('global');
store.inscrits = store.inscrits || [];
const id = String(b.id || '');

switch (String(b.action || 'list')) {
  case 'set': {
    const row = store.inscrits.find((r) => r.id === id);
    if (!row) return [{ json: { ok: false, error: 'introuvable' } }];
    row.winner = b.value === 'Oui';
    return [{ json: { ok: true } }];
  }
  case 'delete': {
    const i = store.inscrits.findIndex((r) => r.id === id);
    if (i < 0) return [{ json: { ok: false, error: 'introuvable' } }];
    store.inscrits.splice(i, 1);
    return [{ json: { ok: true } }];
  }
  default:
    return [{ json: { ok: true, inscrits: store.inscrits } }];
}
